// Process files and extract company name from folder
const folderName = $node["Google Drive Trigger"].json.name;
const folderId = $node["Google Drive Trigger"].json.id;
const response = $input.first().json;

const files = response.files || [];

if (files.length === 0) {
  console.log('No PDF files found in the new folder');
  return [];
}

// Extract company name from folder name
let companyName = folderName || 'Unknown_Company';
companyName = companyName
  .replace(/^(new folder|folder|untitled|document)$/i, 'Unknown_Company')
  .replace(/[_-]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

if (companyName.length < 2 || /^(new|folder|doc|file|temp|test)$/i.test(companyName)) {
  companyName = 'Unknown_Company';
}

console.log(`Processing ${files.length} PDF files for company: ${companyName}`);

return files.map(file => ({
  json: {
    id: file.id,
    name: file.name,
    size: file.size,
    mimeType: file.mimeType,
    company_name: companyName,
    folder_id: folderId,
    original_folder_name: folderName,
    processed: false
  }
}));

// Process extracted PDF text and prepare for vector storage
const extractedData = $input.first().json;
const fileList = $node["Process Files List"].json;

// Get the extracted text
let fullText = '';
if (extractedData && extractedData.data) {
  fullText = extractedData.data;
} else if (typeof extractedData === 'string') {
  fullText = extractedData;
}

if (!fullText || fullText.length < 100) {
  console.error('PDF text extraction failed or text too short');
  return {
    json: {
      error: 'Text extraction failed',
      file_name: fileList.name || 'Unknown',
      company_name: fileList.company_name || 'Unknown'
    }
  };
}

console.log(`Extracted ${fullText.length} characters from ${fileList.name}`);

// Split text into chunks for better vector storage
const chunkSize = 1000; // characters per chunk
const overlap = 200; // overlap between chunks
const chunks = [];

for (let i = 0; i < fullText.length; i += (chunkSize - overlap)) {
  const chunk = fullText.substring(i, i + chunkSize);
  if (chunk.trim().length > 50) { // Only include meaningful chunks
    chunks.push({
      content: chunk.trim(),
      metadata: {
        file_name: fileList.name,
        company_name: fileList.company_name,
        file_id: fileList.id,
        folder_id: fileList.folder_id,
        chunk_index: chunks.length,
        total_chunks: Math.ceil(fullText.length / (chunkSize - overlap)),
        extracted_at: new Date().toISOString()
      }
    });
  }
}

console.log(`Created ${chunks.length} text chunks for vector storage`);

// Return all chunks as separate items
return chunks.map(chunk => ({
  json: {
    pageContent: chunk.content,
    metadata: chunk.metadata
  }
}));

// Log successful vector storage with detailed information
const input = $input.first().json;
const metadata = input.metadata || {};

console.log('✅ Successfully stored vectors in Pinecone');
console.log('📄 File processed:', metadata.file_name || 'Unknown file');
console.log('🏢 Company:', metadata.company_name || 'Unknown');
console.log('📊 Chunk:', `${metadata.chunk_index + 1}/${metadata.total_chunks}`);
console.log('🕐 Timestamp:', new Date().toISOString());

return {
  json: {
    success: true,
    message: '✅ Vector storage completed successfully',
    file_processed: metadata.file_name || 'Unknown',
    company: metadata.company_name || 'Unknown',
    chunk_info: `${metadata.chunk_index + 1}/${metadata.total_chunks}`,
    file_id: metadata.file_id,
    folder_id: metadata.folder_id,
    timestamp: new Date().toISOString(),
    vector_dimensions: '1024 (mxbai-embed-large)',
    pinecone_index: 'n8n'
  }
};

// Final completion summary
const allResults = $input.all();
const successCount = allResults.filter(r => r.json.success).length;
const totalChunks = allResults.length;

const firstResult = allResults[0]?.json || {};
const company = firstResult.company || 'Unknown';
const fileName = firstResult.file_processed || 'Unknown';

console.log('🎉 RAG PROCESSING COMPLETE!');
console.log(`📊 Successfully processed: ${successCount}/${totalChunks} chunks`);
console.log(`🏢 Company: ${company}`);
console.log(`📄 File: ${fileName}`);
console.log('💾 Vectors stored in Pinecone index: n8n');
console.log('🔍 Ready for RAG queries!');

return {
  json: {
    processing_complete: true,
    success_rate: `${successCount}/${totalChunks}`,
    company_processed: company,
    file_processed: fileName,
    total_chunks: totalChunks,
    successful_chunks: successCount,
    pinecone_index: 'n8n',
    embedding_model: 'mxbai-embed-large (1024 dimensions)',
    timestamp: new Date().toISOString(),
    status: '🎉 Ready for RAG queries!'
  }
};
